  ],
  "contradictory_card_ids": ["C39"],
  "prediction_basis_card_ids": [
    "C01", "C02", "C06", "C10", "C11", "C12", "C15", "C17", "C20", "C26", "C34", "C50",
    "C57", "C65", "C73", "C81", "C87", "C91", "C93", "C95", "C98"
  ],
  "claims": [
    {
      "claim": "The closest structural analog esaxerenone has absolute oral bioavailability of 89.0% fasted and 90.8% fed in healthy subjects, and elinzanetant, a lipophilic amide with CF3 and heterocyclic features, has F = 36.7%; both support F >= 20% for this lipophilic amide chemotype.",
      "card_ids": ["C01", "C02", "C10", "C11", "C12", "C20", "C34", "C15", "C17", "C26"]
    },
    {
      "claim": "Nilotinib, the closest lipophilic heteroaryl amide analog with an assumed absolute F of 31% under fasted conditions, shows measurable oral Cmax values in L3 (2010 ng/mL at 400 mg bid; 4.12 µg/mL with a lipid formulation), reinforcing that this chemotype achieves oral exposure above the F >= 20% threshold despite solubility limitations.",
      "card_ids": ["C06", "C50", "C87", "C91"]
    },
    {
      "claim": "Other lipophilic amide/heteroaryl reference molecules with CF3 or OCF3 motifs show substantial oral AUC/Cmax: M08 AUC 31.9-82.3 µg·h/mL across fed/fasted doses, M10 AUCinf 11,200 ng·h/mL after 300 mg, M14 Cmax 1,557 ng/mL after 400 mg, and M15 Cmax 2.9 µg/mL with AUC0-24 50.9 µg·h/mL after 200 mg.",
      "card_ids": ["C65", "C73", "C95", "C98", "C93", "C57", "C81"]
    },
    {
      "claim": "No L3 record provides a direct absolute F value for the query or a sub-20% oral exposure outcome; the family is supportive exposure context, not a new gold vote.",
      "card_ids": ["C87", "C91", "C65", "C73", "C95", "C98", "C93", "C57", "C81"]
    },
    {
      "claim": "The only sub-20% value in visible evidence is isradipine in healthy subjects (16%, C39), but isradipine is structurally dissimilar and low-transferability; it does not outweigh the positive lipophilic amide analogs.",
      "card_ids": ["C39"]
    },
    {
      "claim": "The low physicochemical prior (logD 5.82, unfavorable solubility) remains an uncertain prior; measurable oral exposure in structurally related lipophilic amides supports that solubility limitations do not affirmatively establish F < 20%.",
      "card_ids": ["C87", "C91", "C65", "C73", "C95", "C98", "C93", "C57", "C81"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C87", "C91", "C65", "C73", "C95", "C98", "C93", "C57", "C81"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "L3 provides only AUC/Cmax exposure values, not F values, for reference molecules; no direct F for the query.",
    "No experimental solubility, permeability, or first-pass data for the query; the low prior is physicochemical only.",
    "No dose, formulation, or food-effect data for the query, so solubility-limited absorption cannot be quantified.",
    "Nilotinib F is an assumed value and is precipitation-limited; transfer from other lipophilic amides is qualitative.",
    "L3 records come from diverse chemotypes, so structural transfer to the query is moderate at best."
  ],
  "decision_summary": "Keep high prediction at moderate confidence. L3 oral exposure records add supportive context: nilotinib (closest analog, F = 31%) and other lipophilic amide/CF3-OCF3 structures show measurable oral AUC/Cmax, indicating that high logD does not affirmatively preclude F >= 20%. No L3 record provides a direct F value or sub-20% outcome for the query; the low physicochemical prior remains an uncertain prior, not affirmative evidence for low."
}

